fields.InputDefinition:
{
  "goal": "Assume you are already logged in at http://localhost:4200. Open 'Bulk Operations' and select the 'Run History' section in the left-nav rail. If one or more runs are listed, click a run row to drill in: the view should switch to a detail view headed by the operation name and time, with a 'Back' button and per-record outcome rows (each showing status and any field changes as old → new, OR a 'No per-record details recorded for this run.' message). Click 'Back' to return to the run list. If instead the list shows 'No runs yet.', click 'Refresh' and confirm the empty state is handled cleanly. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away. Either drilling into a run detail (when runs exist) or a clean 'No runs yet.' empty state is success.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "When runs exist, clicking a run opens a detail view with a 'Back' button and per-record outcomes (field diffs or a 'No per-record details' note); Back returns to the list",
    "When no runs exist, the 'No runs yet.' empty state renders and 'Refresh' works without error",
    "No error messages, blank screens, or crash pages"
  ]
}
